pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testRegression_property() public {
        address nonApproved = address(0x1234);
        vm.prank(nonApproved);
        bool result;
        try c.logGotRedemptionSignature(bytes32(0), bytes32(0), bytes32(0)) returns (bool r) {
            result = r;
        } catch {
            result = false;
        }
        assertTrue(result == false);
    }
}
